CREATE TYPE "PaymentPurpose" AS ENUM ('ECOMMERCE_ORDER', 'VENDOR_SUBSCRIPTION', 'WALLET_TOPUP');
CREATE TYPE "PaymentStatus" AS ENUM ('CREATED', 'PENDING', 'PAID', 'FAILED', 'REFUNDED');
CREATE TABLE "payments" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"purpose" "PaymentPurpose" NOT NULL,"referenceId" TEXT NOT NULL,"amountPaise" INTEGER NOT NULL,"currency" TEXT NOT NULL DEFAULT 'INR',"status" "PaymentStatus" NOT NULL DEFAULT 'CREATED',"gateway" TEXT NOT NULL DEFAULT 'RAZORPAY',"gatewayOrderId" TEXT,"gatewayPaymentId" TEXT,"failureCode" TEXT,"failureDescription" TEXT,"paidAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "payments_pkey" PRIMARY KEY ("id"));
CREATE TABLE "payment_webhook_events" ("id" TEXT NOT NULL,"gateway" TEXT NOT NULL DEFAULT 'RAZORPAY',"gatewayEventId" TEXT,"eventType" TEXT NOT NULL,"payload" JSONB NOT NULL,"processedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "payment_webhook_events_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "payments_gatewayOrderId_key" ON "payments"("gatewayOrderId"); CREATE UNIQUE INDEX "payments_gatewayPaymentId_key" ON "payments"("gatewayPaymentId"); CREATE UNIQUE INDEX "payment_webhook_events_gatewayEventId_key" ON "payment_webhook_events"("gatewayEventId"); CREATE INDEX "payments_userId_createdAt_idx" ON "payments"("userId", "createdAt"); CREATE INDEX "payments_purpose_referenceId_idx" ON "payments"("purpose", "referenceId"); CREATE INDEX "payments_status_createdAt_idx" ON "payments"("status", "createdAt"); CREATE INDEX "payment_webhook_events_eventType_createdAt_idx" ON "payment_webhook_events"("eventType", "createdAt");
ALTER TABLE "payments" ADD CONSTRAINT "payments_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
